<!DOCTYPE html>
<html>
<head>
<title>WastedToken Mint</title>
<style>
body {
  font-family: sans-serif;
  margin: 0;
  overflow: hidden;
}

#hero-container {
  width: 100%;
  height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #f0f0f0;
}

#coin-hero {
  width: 200px;
  height: 200px;
}

.edition {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 20px;
  width: 150px;
}

.edition-canvas {
  width: 150px;
  height: 150px;
}

.buy {
  padding: 10px 20px;
  background-color: #4CAF50;
  color: white;
  border: none;
  cursor: pointer;
  display: block;
  width: 100%;
  text-align: center;
}

.buy:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

#about-section {
  padding: 20px;
  background-color: #fff;
  margin: 20px;
  text-align: center;
  border-radius: 10px;
}
</style>
</head>
<body>

<div id="hero-container">
  <canvas id="coin-hero"></canvas>
</div>

<div id="about-section">
  <h2>About WastedToken Mint</h2>
  <p>WastedToken Mint specializes in crafting high-quality, limited-edition challenge coins. Each coin is meticulously designed and hand-minted, making them a coveted collectible for enthusiasts and collectors worldwide. We pride ourselves on delivering exceptional craftsmanship and unique designs that capture the spirit of achievement.</p>
</div>

<div class="edition" data-edition="bronze" data-state="available">
  <canvas class="edition-canvas"></canvas>
  <button class="buy">Add to cart</button>
</div>
<div class="edition" data-edition="silver" data-state="available">
  <canvas class="edition-canvas"></canvas>
  <button class="buy">Add to cart</button>
</div>
<div class="edition" data-edition="gold" data-state="sold-out">
  <canvas class="edition-canvas"></canvas>
  <button class="buy" disabled>SOLD OUT</button>
</div>
<div class="edition" data-edition="black" data-state="coming-soon">
  <canvas class="edition-canvas"></canvas>
  <button class="buy">Add to cart</button>
</div>


<script>
const canvas = document.getElementById('coin-hero');
const ctx = canvas.getContext('2d');

let time = 0;
let rotationSpeed = 0.02;

function renderFrame() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  time += 0.016; // Adjust for frame rate - roughly 60fps
  const angle = time * rotationSpeed;

  ctx.save();
  ctx.translate(canvas.width / 2, canvas.height / 2);
  ctx.rotate(angle);

  // Coin parameters (adjust as needed)
  const coinRadius = 80;
  const bevelWidth = 5; // Reeded edge width
  const frontColor = '#9e9e9e';
  const backColor = '#4CAF50';
  const tokenCount = "10,000 TOKENS";

  // Front face rendering
  ctx.fillStyle = frontColor;
  ctx.beginPath();
  ctx.arc(0, 0, coinRadius, 0, Math.PI * 2);
  ctx.fill();

  // Beveled edge (simplified) - this could be improved significantly with shader code
  ctx.fillStyle = frontColor;
  for (let i = 0; i < bevelWidth; i++) {
    ctx.beginPath();
    ctx.arc(0, 0, coinRadius - i, 0, Math.PI * 2);
    ctx.fill();
  }

  // Back face rendering
  ctx.fillStyle = backColor;
  ctx.fillText(tokenCount, 0, 50);


  // Metallic effect (very basic)
  ctx.fillStyle = '#cdd0e0'; // lighter grey for highlight
  ctx.beginPath();
  ctx.arc(0, 0, coinRadius + 10, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}


window.demo = {
  canvas,
  setTime: (t) => {
    time = t;
    renderFrame();
  },
  pause: () => {
    clearTimeout(timer);
  }
};

const timer = setTimeout(renderFrame, 0); // Initial render

window.addEventListener('resize', () => {
  canvas.width = 200;
  canvas.height = 200;
});


</script>

</body>
</html>
